// src/client/features/web-ai/login-checks.ts
async function checkWebsiteLogin(getController, options = {}) {
  const timeout = options.timeoutMs ?? 12e3, interval = options.intervalMs ?? 1e3, active = options.active || (() => true), deadline = Date.now() + timeout;
  let expired = false, timer;
  const unknown = () => authenticationSummary(null);
  const work = async () => {
    try {
      const controller = await getController();
      while (!expired && active() && Date.now() < deadline) {
        const result = authenticationSummary(await controller.authentication?.());
        if (expired || !active()) return unknown();
        if (result.status !== "unknown") return result;
        const remaining = deadline - Date.now();
        if (remaining <= 0) break;
        await new Promise((resolve) => setTimeout(resolve, Math.min(interval, remaining)));
      }
    } catch {
    }
    return unknown();
  };
  try {
    return await Promise.race([work(), new Promise((resolve) => {
      timer = setTimeout(() => {
        expired = true;
        resolve(unknown());
      }, timeout);
    })]);
  } finally {
    expired = true;
    clearTimeout(timer);
  }
}

